  project:{title:"Comparing connected societies",brief:"Prepare a source-based comparison of Aksum and one Swahili town using printed notes and a map.",steps:["Locate both places and identify their trade connections.","Describe one local contribution and one outside influence in each.","Present evidence and explain one limit of the comparison."],criteria:["accurate locations","recognition of African agency","supported comparison"]},
