  project:{title:"Comparing four administrations",brief:"Compare Roberts, Barclay, Tubman and Tolbert using classroom notes and printed sources.",steps:["List one policy or challenge associated with each president.","Distinguish policy aims from evidence about outcomes.","Write a comparison identifying continuity and change."],criteria:["correct leaders and chronology","balanced evidence","clear comparison"]},
  activities:["Build a three-branch government chart.","Discuss border pressures using historical maps.","Analyse causes and consequences of the 1980 coup without role-playing violence."],
