  sort:{title:"Forms of external action",groups:[{name:"Bilateral relations",items:["Liberia–United States diplomatic exchange","Trade talks between Liberia and Japan"]},{name:"Multilateral relations",items:["Liberian participation at the UN","ECOWAS regional negotiations"]}]},
  mapwork:{title:"Liberia's international cooperation timeline",caption:"Make a timeline linking Liberia to the founding or development of these organisations.",items:[{p:"1920",f:"League of Nations begins with Liberia as an original member"},{p:"1945",f:"United Nations founded; Liberia is an original member"},{p:"1963",f:"OAU founded with Liberia participating"},{p:"1973",f:"Mano River Union founded"},{p:"1975",f:"ECOWAS founded"},{p:"2002",f:"AU succeeds the OAU"}]},
  casestudy:{title:"Negotiating a shared problem",text:"A fictional border district faces a disease outbreak and disrupted trade. Liberian officials consult neighbouring governments and a regional organisation rather than assuming the problem can be solved within one country's borders.",questions:[{q:"Why is international cooperation relevant?",a:"Disease and trade routes cross borders, so action in one country affects others."},{q:"What makes talks bilateral or multilateral?",a:"Two states conduct bilateral talks; several states or an organisation's members engage multilaterally."},{q:"What should officials assess before an agreement?",a:"Public needs, legal authority, obligations, resources and likely benefits and risks."}]},
